.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.brand {
  max-width: 720px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  font-weight: 600;
  letter-spacing: 0.01em;
