.page {
  max-width: 640px;
  margin: 2.5rem auto;
  padding: 0 1.25rem;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow);
  padding: 2rem;
}

h1 {
  font-size: 1.625rem;
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
}

.lede {
  margin: 0 0 1rem;
  color: var(--muted);
}

.required-legend {
  margin: 0 0 1.5rem;
  font-size: 0.875rem;
  color: var(--muted);
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

label {
  font-weight: 600;
  font-size: 0.95rem;
}

.req { color: var(--error); margin-left: 0.125rem; }

.optional {
  font-weight: 400;
  color: var(--muted);
  font-size: 0.875rem;
}

input {
  font: inherit;
  color: var(--text);
  background: #fff;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  width: 100%;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

input:hover { border-color: #334155; }

input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

input[aria-invalid="true"] {
  border-color: var(--error);
}
input[aria-invalid="true"]:focus-visible {
  outline-color: var(--error);
  border-color: var(--error);
}

.help {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.error {
  margin: 0;
  font-size: 0.875rem;
  color: var(--error);
  font-weight: 500;
}

.actions {
  margin-top: 1.5rem;
}

.btn-primary {
  font: inherit;
  font-weight: 600;
  background: var(--primary);
  color: #fff;
  border: 1px solid var(--primary);
  padding: 0.7rem 1.25rem;
  border-radius: var(--radius);
  cursor: pointer;
  min-height: 44px;
  transition: background-color 120ms ease;
}
.btn-primary:hover { background: var(--primary-hover); border-color: var(--primary-hover); }
.btn-primary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  margin: 1rem 0 0;
  min-height: 1.25rem;
  font-size: 0.95rem;
}
.status.success { color: #047857; font-weight: 600; }

@media (forced-colors: active) {
  input { border: 1px solid CanvasText; }
  input:focus-visible { outline: 3px solid Highlight; }
  .btn-primary { border: 1px solid ButtonText; }
}

@media (max-width: 420px) {
  .card { padding: 1.25rem; }
  .page { margin: 1.25rem auto; }
}
