  const form = document.getElementById('contact-form');
  const status = document.getElementById('form-status');

  const fields = {
    name: {
      input: document.getElementById('name'),
      error: document.getElementById('name-error'),
      validate(value) {
        if (!value.trim()) return 'Error: Enter your full name.';
        return '';
      },
    },
    email: {
      input: document.getElementById('email'),
      error: document.getElementById('email-error'),
      validate(value) {
        const v = value.trim();
        if (!v) return 'Error: Enter your email address.';
        // Simple, permissive email check
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!re.test(v)) return 'Error: Enter a valid email like name@example.com.';
        return '';
      },
    },
    phone: {
      input: document.getElementById('phone'),
      error: document.getElementById('phone-error'),
      validate(value) {
        const v = value.trim();
        if (!v) return ''; // optional
        // Allow digits, spaces, +, -, parentheses; require 7-15 digits total
        if (!/^[+\d\s().-]+$/.test(v)) {
          return 'Error: Phone number can only contain digits, spaces, and + ( ) -';
        }
        const digits = v.replace(/\D/g, '');
        if (digits.length < 7 || digits.length > 15) {
          return 'Error: Enter a phone number with 7 to 15 digits, e.g. +1 555 123 4567.';
        }
        return '';
      },
    },
  };

  function setError(field, message) {
    if (message) {
      field.error.textContent = message;
      field.error.hidden = false;
      field.input.setAttribute('aria-invalid', 'true');
    } else {
      field.error.textContent = '';
      field.error.hidden = true;
      field.input.setAttribute('aria-invalid', 'false');
    }
  }

  // Re-validate on blur, and clear errors as the user fixes them
  Object.values(fields).forEach((field) => {
    field.input.addEventListener('blur', () => {
      setError(field, field.validate(field.input.value));
    });
    field.input.addEventListener('input', () => {
      if (field.input.getAttribute('aria-invalid') === 'true') {
        const msg = field.validate(field.input.value);
        if (!msg) setError(field, '');
      }
    });
  });

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    status.textContent = '';
    status.classList.remove('success');

    let firstInvalid = null;
    Object.values(fields).forEach((field) => {
      const msg = field.validate(field.input.value);
      setError(field, msg);
      if (msg && !firstInvalid) firstInvalid = field.input;
    });

    if (firstInvalid) {
      firstInvalid.focus();
      status.textContent = 'Please fix the errors above and try again.';
      return;
    }

    status.textContent = 'Thanks! Your message has been sent. We\u2019ll be in touch shortly.';
    status.classList.add('success');
    form.reset();
    Object.values(fields).forEach((field) => setError(field, ''));
  });
})();
